import{_ as i,l as o,o as e,c as s,v as r,p as n,x as l,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"内核加固","description":"","frontmatter":{"title":"内核加固","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-hardening.md","filePath":"cs/kernel-hardening.md","lastUpdated":1789023840000}'),E={name:"cs/kernel-hardening.md"};function A(h,a,_,u,f,S){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="内核加固" tabindex="-1">内核加固 <a class="header-anchor" href="#内核加固" aria-label="Permalink to &quot;内核加固&quot;">​</a></h1><div class="epigraph"><p>加固是一组降低利用价值的默认：KASLR、SMEP/SMAP、W^X、栈金丝雀、控制流完整性，而不是一个新的调度器。</p><footer>—— 据 Linux kernel self-protection 文档；PaX/grsecurity 的历史直觉；Intel/ARM 对 SMEP/PAN 的说明</footer></div><p><a href="/cs/kpti-os">KPTI</a> 是侧信道专项。<a href="/cs/linux-capabilities">capabilities</a> 在安全课序。缺口是 <strong>内存与控制流加固</strong> 在 OS 的落点：攻击面从「任意读写」变成「还要过这些门」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>漏洞仍在。KASLR：内核映像随机。SMEP：用户页不能在内核态执行。SMAP/PAN：内核不能随意碰用户数据，必须显式开关。栈金丝雀：<code>__stack_chk</code>。CFI：间接跳转检查。缺口：每一项的性能与调试税；与模块签名后课接头。本课不把 exploit 写成教程，只讲防御机制。</p><p><span class="marginnote">lockdown、seccomp 是策略。本课偏硬件+编译器协助的内存安全。不要写成 LLM 对齐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译：KASAN 可选（后课 ASan 用户态亲戚）；发布内核开 canary、fortify。运行：CPU 控制寄存器开 SMEP。对照 <a href="/cs/lsm-selinux">LSM</a>：LSM 是访问控制；加固是利用缓解。对照 <a href="/cs/vmalloc">vmalloc</a>：执行权限与 W^X 限制可执行 vmalloc。</p>',8)),(e(),n(p,null,{default:l(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUG%5B%22%E5%86%85%E5%AD%98%E6%BC%8F%E6%B4%9E%22%5D%20--%3E%20KASLR%5B%22%E5%9C%B0%E5%9D%80%E4%B8%8D%E7%A1%AE%E5%AE%9A%22%5D%0A%20%20BUG%20--%3E%20SMEP%5B%22%E4%B8%8D%E8%83%BD%E6%89%A7%E8%A1%8C%E7%94%A8%E6%88%B7%E9%A1%B5%22%5D%0A%20%20BUG%20--%3E%20NX%5B%22%E6%95%B0%E6%8D%AE%E9%A1%B5%E4%B8%8D%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A%20%20BUG%20--%3E%20CFI%5B%22%E9%97%B4%E6%8E%A5%E8%B0%83%E7%94%A8%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>加固把利用链变长、变不稳，使远程代码执行更难。它不修逻辑 bug。不要写成杀毒软件。与 <a href="/cs/userfaultfd">userfaultfd</a>：加固不禁止合法 uffd。与 DPDK：用户态驱动仍要 IOMMU，那是 DMA 下一课。</p><p>调试：KASLR 使 oops 符号要 kallsyms；生产与调试内核配置分裂。</p><p>实现上：KASLR 熵受内存布局和模块加载影响，不是密码学密钥。SMAP 在 copy_from_user 路径要 stac/clac。CFI 误报会直接 oops，调试内核有时关。 读法上只引用<a href="/cs/kpti-os">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>内核加固</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每一项 CONFIG_ 的依赖图。不保证实时内核上 CFI 的延迟。下一课设备 DMA 如何与缓存/IOMMU 一致。</p><p>版本字段会变，课序钉的是机制对象「内核加固」，不是某一主线内核的结构体名。 后课默认：内核默认带多层利用缓解。DMA 与一致性，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>加固：随机化、W^X、SMEP/SMAP、金丝雀、CFI。</li><li>与 LSM 分工：缓解利用 vs 访问策略。</li><li>DMA 一致性是下一课。</li><li>出处：KSPP 文档；硬件手册 SMEP；Linux 安全文档。</li></ul>',11))])}const M=i(E,[["render",A]]);export{m as __pageData,M as default};
